sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 color3;
uniform float repeat;
uniform float phase;
uniform float reverse;
uniform float scaleBrightness;
uniform float opacity;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float w = luma(base) * repeat + phase;
    float u = 1.0 - abs(fract(w * 0.5) * 2.0 - 1.0);
    if (reverse > 0.5) u = 1.0 - u;
    float4 g = u < 0.5 ? mix(float4(color1), float4(color2), u * 2.0) : mix(float4(color2), float4(color3), u * 2.0 - 1.0);
    float3 mapped = scaleBrightness > 0.5 ? g.rgb * luma(base) : g.rgb;
    float3 rgb = mix(base, mapped, clamp(opacity, 0.0, 1.0) * g.a);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
